def button(text, cls=''):return f'<button class="btn {cls}" onclick="demo()">{text}</button>'
def phone(title,body,foot):return f'<div class="phone"><div class="status">9:41 <span style="float:right">▰ ▰ ▰</span></div><div class="nav"><span>‹</span>{title}<span class="capsule">•••　◉</span></div><div class="content">{body}</div><div class="footer">{foot}</div></div>'
def card(s):return '<div class="card">'+s+'</div>'
def person(n,sub,label='',alt=False):return f'<div class="row person"><div class="avatar {"alt" if alt else ""}">{n[0]}</div><div class="grow"><b>{n}</b><div class="muted">{sub}</div></div><span class="tag">{label}</span></div>'
def board(num,title,desc,items):
    h=f'<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>{title}</title><style>{css}</style><header><h1>{num}　{title}</h1><p>{desc}　·　方案 v1 / 待确认 / 示例人物与内容</p></header><nav><a href="24.html">24 特邀码</a><a href="25.html">25 图片</a><a href="27.html">27 学友</a></nav><main class="board">'
    for cap,view,note in items:h+=f'<section class="col"><div class="caption">{cap}</div>{view}<div class="below">{note}</div></section>'
    h+='</main><div class="toast" id="toast">设计演示：此操作不提交数据，实际功能待确认后开发。</div><script>function demo(){let t=document.getElementById("toast");t.style.display="block";setTimeout(()=>t.style.display="none",2500)}</script></html>'
    (ROOT/f'{num}.html').write_text(h,encoding='utf-8')

